// gen-apply-trial-bundle.mjs - builds supabase/APPLY-TRIAL-BUNDLE.sql: ONE paste for the Supabase SQL
// editor that applies the whole free-trial release in order:
//   APPLY-0173 .. APPLY-0187 (each file that exists, verbatim, each in its own begin / commit),
//   then FIX-0177-existing-trials.sql, then APPLY-0178-refresh-trials.sql LAST,
//   then ONE combined VERIFY grid (the last result the editor shows; every row must say ok = true).
// Every section is the owner-reviewed paste file unchanged, so the bundle is exactly "paste them one
// by one". No temp tables, no session settings; safe to paste twice (every section is idempotent).
//   node scripts/gen-apply-trial-bundle.mjs           rewrite supabase/APPLY-TRIAL-BUNDLE.sql
//   node scripts/gen-apply-trial-bundle.mjs --check   exit 1 if it is out of date
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
const ROOT = new URL('..', import.meta.url).pathname;
const r = (p) => readFileSync(ROOT + p, 'utf8');
const OUT = 'supabase/APPLY-TRIAL-BUNDLE.sql';

const sections = [];
for (let n = 173; n <= 187; n++) {
  const p = `supabase/APPLY-0${n}.sql`;
  if (existsSync(ROOT + p)) sections.push({ n: '0' + n, p });
}
sections.push({ n: 'FIX-0177', p: 'supabase/FIX-0177-existing-trials.sql' });
sections.push({ n: '0178', p: 'supabase/APPLY-0178-refresh-trials.sql' });

const VSTART = 'select item, ok from (values\n';
const VEND = /\n\) v\(item, ok\) order by item;\s*$/;
const verify = [];
let body = '';
sections.forEach((s, i) => {
  const src = r(s.p).replace(/\s*$/, '\n');
  if (/[^\x09\x0a\x0d\x20-\x7e]/.test(src)) throw new Error(s.p + ': not ASCII');
  if (/^\s*\\/m.test(src)) throw new Error(s.p + ': psql meta-command (not pasteable)');
  if (/\bcreate\s+(temp|temporary)\s+table\b/i.test(src)) throw new Error(s.p + ': temp table (not pasteable)');
  body += `\n-- ##########################################################################################\n`
        + `-- SECTION ${String(i + 1).padStart(2, '0')}/${sections.length}: ${s.p.replace('supabase/', '')}`
        + (s.n === '0178' ? '  (LAST: refreshes the existing trial studios to the current sample)' : '') + '\n'
        + `-- ##########################################################################################\n` + src;
  if (/^0\d{3}$/.test(s.n) && s.n !== '0178') {
    const at = src.lastIndexOf(VSTART);
    if (at < 0 || !VEND.test(src)) throw new Error(s.p + ': VERIFY block missing or not in the expected shape');
    const rows = src.slice(at + VSTART.length).replace(VEND, '');
    verify.push(`select '${s.n} ' || item as item, ok from (values\n${rows}\n) v(item, ok)`);
  } else if (s.n === 'FIX-0177') {
    const m = src.match(/-- 3\) VERIFY[^\n]*\n(select [\s\S]*?);\s*$/);
    if (!m) throw new Error(s.p + ': VERIFY query not found');
    verify.push(`select 'FIX-0177 no self-serve trial studio left off the India defaults' as item,\n  not exists (\n${m[1]}\n) as ok`);
  } else {
    const m = src.match(/-- ---- 3\) VERIFY[^\n]*\n(select [\s\S]*?);\s*$/);
    if (!m) throw new Error(s.p + ': VERIFY query not found');
    verify.push(`select 'REFRESH-0178 every trial studio on the current sample, India, 4 sample venues, no queued send' as item,\n  not exists (select 1 from (\n${m[1]}\n) z where not coalesce(z.ok, false)) as ok`);
  }
});

const list = sections.map((s, i) => `--   ${String(i + 1).padStart(2, '0')}  ${s.p.replace('supabase/', '')}`).join('\n');
const out = `-- APPLY-TRIAL-BUNDLE.sql - ONE paste for the Supabase SQL editor: the whole free-trial release.
-- GENERATED by scripts/gen-apply-trial-bundle.mjs from the paste files below - edit those, not this.
-- Run on STAGING first, check the last result grid, then on PRODUCTION only when the owner says go.
--
-- What it runs, in this order (each section is that file unchanged, each in its own transaction):
${list}
-- Paid studios are not changed. Rows are only written where a section says so: FIX-0177 (India
-- defaults on existing self-serve trials) and REFRESH-0178 (each existing trial studio's SAMPLE rows
-- are cleared and cloned again from the current sample; the studio's own rows are kept). The trial
-- retention deletion (0184) is installed SWITCHED OFF - nothing is ever deleted unless the owner
-- turns it on later with its own SQL statement.
-- Safe to paste twice: every section is idempotent (the second paste changes nothing).
-- If a section stops with an error, fix the cause and paste the whole file again.
--
-- The LAST result grid is the combined VERIFY: every row must say ok = true. (0184 row 03 says
-- false only once the owner has switched trial deletion on - expected then.)
${body}
-- ##########################################################################################
-- COMBINED VERIFY (read-only): every row must say ok = true
-- ##########################################################################################
${verify.join('\nunion all\n')}
order by 1;
`;
if (/[^\x09\x0a\x0d\x20-\x7e]/.test(out)) throw new Error('bundle is not ASCII');
if (process.argv.includes('--check')) {
  let cur = ''; try { cur = r(OUT); } catch {}
  if (cur !== out) { console.error(OUT + ' is out of date (node scripts/gen-apply-trial-bundle.mjs)'); process.exit(1); }
  console.log('  ok ' + OUT + ' up to date (' + sections.length + ' sections)');
} else {
  writeFileSync(ROOT + OUT, out);
  console.log('wrote ' + OUT + ' (' + sections.length + ' sections, ' + verify.length + ' VERIFY blocks)');
}
